<script setup lang="ts">
import { computed, ref } from 'vue'
import { motion, useInView, useReducedMotion } from 'motion-v'

const root = ref<HTMLElement>()
const shouldReduceMotion = useReducedMotion()

// Rien ne tourne tant que la carte n'est pas à l'écran : les boucles démarrent
// à l'entrée dans le viewport et repartent de zéro à chaque retour.
const inView = useInView(root, { amount: 0.3 })
const playing = computed(() => inView.value && !shouldReduceMotion.value)

// La page se recompose toutes les 10 secondes : chaque bloc arrive à son tour,
// tout reste affiché l'essentiel du cycle, puis s'efface avant de repartir.
const LOOP = 10
const FADE_OUT = 0.86
const CLEARED = 0.9
const RISE = 0.55

const settled = { opacity: 1, y: 0 }
const instant = { duration: 0.3 } as const
const pressRest = { scale: 1 }

// Hors écran, on repart de la première keyframe.
function rest(offset: number) {
  return { opacity: 0, y: offset }
}

function compose(offset: number) {
  return {
    opacity: [0, 0, 1, 1, 0, 0],
    y: [offset, offset, 0, 0, 0, offset]
  }
}

function cue(start: number) {
  return {
    duration: LOOP,
    times: [0, start / LOOP, (start + RISE) / LOOP, FADE_OUT, CLEARED, 1],
    repeat: Infinity,
    ease: 'easeOut'
  } as const
}

// Le bouton principal respire une fois par cycle, pendant que la page est visible.
const ctaPress = { scale: [1, 1, 0.95, 1, 1] }
const ctaPressTransition = {
  duration: LOOP,
  times: [0, 0.5, 0.535, 0.59, 1],
  repeat: Infinity
} as const
</script>

